29: export const solve = async function (challenge: ChallengeModel, isRestore = false, isCheating = false) {
30:   challenge.solved = true
31:   const solvedChallenge = await challenge.save()
32: 
33:   logger.info(`${isRestore ? colors.grey('Restored') : colors.green('Solved')} ${solvedChallenge.difficulty}-star ${colors.cyan(solvedChallenge.key)} (${solvedChallenge.name})`)
34:   sendNotification(solvedChallenge, isRestore)
35:   if (!isRestore) {
36:     const cheatScore = antiCheat.calculateCheatScore(challenge, isCheating)
37:     const hintsAvailable = await HintModel.count({ where: { ChallengeId: solvedChallenge.id } })
38:     const hintsUnlocked = await HintModel.count({ where: { ChallengeId: solvedChallenge.id, unlocked: true } })
39:     if (process.env.SOLUTIONS_WEBHOOK) {
40:       webhook.notify(solvedChallenge, cheatScore, hintsAvailable, hintsUnlocked).catch((error: unknown) => {
41:         logger.error('Webhook notification failed: ' + colors.red(utils.getErrorMessage(error)))
42:       })
43:     }
44:   }
45: }
